    }
    if (tk.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') fail()
        p++
        return { t: 'range', a: tk.v, b: t2.v }
      }
      const u = tk.v.toUpperCase()
      if (u === 'TRUE') return { t: 'bool', v: true }
      if (u === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', a: tk.v }
    }
    fail()
  }
  try {
    const tree = cmp()
    if (p < toks.length) return null
    return tree
  } catch {
    return null
  }
}

function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r, key: c + ',' + r })
  }
  return out
}

function analyze(tree) {
  const deps = new Map()
  let bad = false
  const addDep = (a) => deps.set(a.key, a)
  function walk(n, direct) {
    switch (n.t) {
      case 'ref': { const a = parseAddr(n.a); if (a) addDep(a); break }
      case 'range': {
        if (!direct) bad = true
        const cs = rangeCells(n)
        if (cs) cs.forEach(addDep)
        break
      }
      case 'bin': walk(n.l, false); walk(n.r, false); break
      case 'un': walk(n.x, false); break
      case 'paren': walk(n.x, false); break
      case 'call': n.args.forEach((x) => walk(x, true)); break
    }
  }
  walk(tree, false)
  return { deps: [...deps.values()].sort((x, y) => x.col - y.col || x.row - y.row), bad }
}

// ---------- literals ----------
function literalValue(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRORS.includes(s)) return err(s)
  return { k: 'text', v: s }
}

// ---------- evaluation ----------
const memo = new Map()
const active = new Set()
const parsed = new Map()

function cellValue(a) {
  const key = a.key
  if (memo.has(key)) return memo.get(key)
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (cell.content[0] === '=') {
    const info = getParsed(cell)
    v = !info.tree || info.bad ? err('#ERR!') : evalNode(info.tree)
  } else v = literalValue(cell.content)
  active.delete(key)
  memo.set(key, v)
  return v
}
function getParsed(cell) {
  let info = parsed.get(cell)
  if (!info) {
    const tree = parseFormula(cell.content.slice(1))
    info = tree ? { tree, ...analyze(tree) } : { tree: null, deps: [], bad: false }
    parsed.set(cell, info)
  }
  return info
}

function toNum(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const kindRank = { num: 0, text: 1, bool: 2 }
function compare(l, r) {
  if (l.k !== r.k) return kindRank[l.k] - kindRank[r.k]
  if (l.k === 'text') {
    const a = [...l.v], b = [...r.v]
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      const d = a[i].codePointAt(0) - b[i].codePointAt(0)
      if (d) return d
    }
    return a.length - b.length
  }
  const x = l.k === 'bool' ? +l.v : l.v
  const y = r.k === 'bool' ? +r.v : r.v
  return x < y ? -1 : x > y ? 1 : 0
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function evalNode(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'bool', v: n.v }
    case 'paren': return evalNode(n.x)
    case 'ref': {
      const a = parseAddr(n.a)
      return a ? cellValue(a) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const x = evalNode(n.x)
      if (x.k === 'err') return x
      const v = toNum(x)
      if (v.k === 'err') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.k === 'err') return l
      if (r.k === 'err') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'bool', v: res }
      }
      const a = toNum(l)
      if (a.k === 'err') return a
      const b = toNum(r)
      if (b.k === 'err') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3 || args.some((a) => a.t === 'range')) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.k === 'err') return c
    let truth
    if (c.k === 'bool') truth = c.v
    else if (c.k === 'num') truth = c.v !== 0
    else return err('#VALUE!')
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (args.length !== 1 || args[0].t === 'range') return err('#ERR!')
    const x = evalNode(args[0])
    if (x.k === 'err') return x
    const v = toNum(x)
    if (v.k === 'err') return v
    return num(Math.abs(v.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.t === 'range') {
      const cs = rangeCells(a)
      if (!cs) vals.push(err('#REF!'))
      else for (const c of cs) vals.push(cellValue(c))
    } else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.k === 'err')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => Math.min(s, x)))
    case 'MAX': return num(nums.reduce((s, x) => Math.max(s, x)))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'err': return v.e
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

let out = ''
for (const c of sorted) {
  const name = addrName(c.addr)
  if (mode === 'values') out += `${name}=${show(cellValue(c.addr))}\n`
  else {
    let d = []
    if (c.content[0] === '=') d = getParsed(c).deps
    out += `${name}:${d.map((a) => ' ' + addrName(a)).join('')}\n`
  }
}
process.stdout.write(out)
